import React, { useState } from 'react';
import { Link } from 'gatsby';
import { useTranslation } from 'gatsby-plugin-react-i18next';
import { FiArrowUp, FiMenu, FiX } from "react-icons/fi";
import data from '../data/data.json';

export default function Navigation() {
  const { t } = useTranslation();
  const [menuOpen, setMenuOpen] = useState(false);
  const toggleMenu = () => setMenuOpen(!menuOpen);
  const menuItems = data.menu;
  return (
    <nav className="relative">
      {/* Desktop Menu */}
      <div className="hidden md:flex gap-6 items-center text-base">
        {menuItems.map((key) => (
          <Link
            key={key}
            to={key === "about-us" ? "/" : t(`/${key}`)}
            className= "text-accent text-xl  px-2 py-2 hover:underline"
          >
            {t(`menu.${key}`)}
          </Link>
        ))}
      </div>

      {/* Mobile Menu Button */}
      <div className={"md:hidden flex"}>
        <button onClick={toggleMenu} aria-label="Toggle menu">
          {menuOpen ? <FiX size={36} className="fixed z-50 right-4 top-4 text-accent" /> : <FiMenu size={36} className="text-accent" />}
        </button>
      </div>

      {/* Mobile Menu Panel */}
      {menuOpen && (
        <div className="fixed left-0 top-0 w-full bg-white text-center shadow-md p-4 z-40 flex flex-col gap-4 md:hidden">
          {menuItems.map((key) => (
            <Link
              key={key}
              to={key === "about-us" ? "/" : t(`/${key}`)}
              className="hover:text-accent transition-colors"
              onClick={() => setMenuOpen(false)} // Close on click
            >
              {t(`menu.${key}`)}
            </Link>
          ))}
        </div>
      )}
    </nav>
  );
};
